if(!document.PathName.EndsWith("Capilla_ajuste_nuevas_tomas.rvt"))throw new Exception("Documento inesperado");
return new{doors=new FilteredElementCollector(document).OfCategory(BuiltInCategory.OST_Doors).WhereElementIsNotElementType().Cast<FamilyInstance>().Select(f=>new{id=f.Id.Value,host=f.Host?.Id.Value,symbol=f.Symbol.Id.Value,family=f.Symbol.FamilyName,name=f.Name,p=(f.Location as LocationPoint)?.Point.ToString()}).ToList(),shapes=new FilteredElementCollector(document).OfClass(typeof(DirectShape)).Cast<DirectShape>().Where(f=>f.Category.Id.Value!=(long)BuiltInCategory.OST_Planting).Select(f=>new{id=f.Id.Value,name=f.ApplicationDataId}).ToList()};
